const requiredRooms = [
    { key: 'master', room: 'master_bedroom' },
    { key: 'sala', room: 'sala' },
    { key: 'living', room: 'living_room' }
];

let body = msg.payload;
if (typeof body === 'string') {
    try { body = JSON.parse(body); }
    catch (err) { return [null, { topic: 'invalid_json', payload: err.message }]; }
}
if (!body || typeof body !== 'object' || Array.isArray(body)) {
    return [null, { topic: 'invalid_payload', payload: 'Expected a JSON object' }];
}
if (typeof body.device_id !== 'string' || !body.device_id ||
    !Number.isFinite(Number(body.uptime_s))) {
    return [null, { topic: 'invalid_envelope', payload: 'device_id and numeric uptime_s are required' }];
}

const table = env.get('SUPABASE_TABLE') || 'pzem_readings';
const baseUrl = (env.get('SUPABASE_URL') || '').replace(/\/+$/, '');
const apiKey = env.get('SUPABASE_KEY') || '';
if (!/^[A-Za-z_][A-Za-z0-9_]*$/.test(table)) {
    return [null, { topic: 'configuration_error', payload: 'SUPABASE_TABLE must be a simple table name' }];
}
if (!baseUrl || !apiKey) {
    return [null, { topic: 'configuration_error', payload: 'Set SUPABASE_URL and SUPABASE_KEY in this flow tab environment' }];
}

const numericFields = ['voltage', 'current', 'power', 'energy', 'frequency', 'power_factor'];
const rows = [];
const problems = [];
for (const spec of requiredRooms) {
    const reading = body[spec.key];
    if (!reading || typeof reading !== 'object' || Array.isArray(reading) ||
        typeof reading.ok !== 'boolean' || typeof reading.ssr_on !== 'boolean') {
        problems.push(spec.key + ': missing object, boolean ok, or boolean ssr_on');
        continue;
    }
    const row = {
        device_id: body.device_id,
        room: spec.room,
        uptime_s: Math.trunc(Number(body.uptime_s)),
        ok: reading.ok,
        ssr_on: reading.ssr_on
    };
    if (env.get('SUPABASE_GROUP_ID')) row.group_id = env.get('SUPABASE_GROUP_ID');
    let valid = true;
    for (const field of numericFields) {
        const value = reading[field];
        if (reading.ok) {
            if (typeof value !== 'number' || !Number.isFinite(value)) {
                problems.push(spec.key + ': invalid ' + field);
                valid = false;
                break;
            }
            row[field] = value;
        } else if (value === null || value === undefined) {
            row[field] = null;
        } else if (typeof value === 'number' && Number.isFinite(value)) {
            row[field] = value;
        } else {
            problems.push(spec.key + ': invalid unavailable value for ' + field);
            valid = false;
            break;
        }
    }
    if (valid) rows.push(row);
}
if (problems.length) node.warn('Skipped invalid room data: ' + problems.join('; '));
if (!rows.length) return [null, { topic: 'no_valid_rooms', payload: problems }];

msg.method = 'POST';
msg.url = baseUrl + '/rest/v1/' + encodeURIComponent(table) +
    '?on_conflict=device_id,room,uptime_s';
msg.headers = {
    apikey: apiKey,
    Authorization: 'Bearer ' + apiKey,
    'Content-Type': 'application/json',
    Prefer: 'resolution=merge-duplicates,return=minimal'
};
msg.payload = rows;
msg._roomCount = rows.length;
return [msg, problems.length ? { topic: 'partial_validation', payload: problems } : null];

if (msg.statusCode >= 200 && msg.statusCode < 300) {
    msg.payload = { ok: true, statusCode: msg.statusCode, roomsSubmitted: msg._roomCount };
    return msg;
}
node.warn('Supabase write failed, HTTP ' + msg.statusCode + ': ' + JSON.stringify(msg.payload));
msg.topic = 'supabase_error';
return msg;

msg.topic = 'flow_error';
msg.payload = { message: msg.error && msg.error.message ? msg.error.message : 'Unknown Node-RED flow error', source: msg.error && msg.error.source ? msg.error.source.name : 'unknown' };
return msg;
